71	func NewRootCommand(opts Options) *cobra.Command {
72		if opts.Version == "" {
73			opts.Version = "dev"
74		}
75		if opts.Runner == nil {
76			opts.Runner = ExecRunner{}
77		}
78		if opts.Now == nil {
79			opts.Now = time.Now
80		}
81	
82		cmd := &cobra.Command{
83			Use:   "entire-brain",
84			Short: "Build and query a local repository brain for agents",
85			// Version is what makes cobra install `--version` at all:
86			// InitDefaultVersionFlag is a no-op on a command whose Version is
87			// empty, so leaving it unset while carrying the value on Options meant
88			// `--version`, `-v` and `-V` all failed with "unknown flag" on a binary
89			// that knows perfectly well what it is. It is the same string the
90			// `version` subcommand already reports.
91			Version:       opts.Version,
92			SilenceUsage:  true,
93			SilenceErrors: true,
94			Long: `entire-brain is an external-command plugin for the Entire CLI.
95	
96	It builds a local, inspectable repository brain from retained sessions, repository
97	context, docs, history, code-index records, and durable memories, then exposes
98	retrieval, verification, and evaluation surfaces for agents.`,
99			RunE: func(cmd *cobra.Command, args []string) error {
100				return cmd.Help()
101			},
102		}
103		// One binary must not answer "what version are you" two different ways.
104		// cobra's default template prints "entire-brain version X"; `entire-brain
105		// version` prints the bare string, and that is the form scripts already
106		// parse.
107		cmd.SetVersionTemplate("{{.Version}}\n")
108		cmd.Flags().Bool("help-all", false, "List all commands, including hidden commands")
109	
110		// The shell-completion generator targets the standalone binary name and is
111		// dead weight when dispatched as `entire brain`, so drop it entirely.
112		cmd.CompletionOptions.DisableDefaultCmd = true
113	
114		cmd.AddGroup(
115			&cobra.Group{ID: "setup", Title: "Set up the brain & agents:"},
116			&cobra.Group{ID: "explore", Title: "Search & explore the brain:"},
117			&cobra.Group{ID: "facts", Title: "Durable memories & patterns:"},
118			&cobra.Group{ID: "code", Title: "Code index & context:"},
119			&cobra.Group{ID: "maintain", Title: "Brain state & maintenance:"},
120			&cobra.Group{ID: "share", Title: "Workspaces & sharing:"},
121			&cobra.Group{ID: "operations", Title: "Troubleshooting & operations:"},
