221	// setRootUsage preserves the workflow order without changing Cobra's global
222	// sorting setting or the default help for subcommands.
223	func setRootUsage(root *cobra.Command, commands []*cobra.Command) {
224		defaultUsage := root.UsageFunc()
225		defaultHelp := root.HelpFunc()
226		helpWidth := 0
227		root.SetHelpFunc(func(cmd *cobra.Command, args []string) {
228			// Cobra renders UsageString into a buffer; measure the real output first.
229			if cmd == root {
230				helpWidth = helpTerminalWidth(cmd.OutOrStdout())
231				defer func() { helpWidth = 0 }()
232			}
233			defaultHelp(cmd, args)
234		})
235		root.SetUsageFunc(func(cmd *cobra.Command) error {
236			if cmd != root {
237				return defaultUsage(cmd)
238			}
239			type helpEntry struct {
240				command *cobra.Command
241				name    string
242				group   string
243			}
244			var ordered []helpEntry
245			for _, c := range commands {
246				ordered = append(ordered, helpEntry{c, c.Name(), c.GroupID})
247				if c.Name() == "memories" {
248					// Surface operator paths without moving the everyday memories family
249					// or changing any child's registration or visibility.
250					for _, name := range []string{"import", "sync", "proposals", "gc", "vitality"} {
251						for _, child := range c.Commands() {
252							if child.Name() == name {
253								ordered = append(ordered, helpEntry{child, "memories " + name, "operations"})
254							}
255						}
256					}
257				}
258			}
259			for _, c := range cmd.Commands() {
260				if c.Name() == "help" {
261					ordered = append(ordered, helpEntry{c, c.Name(), c.GroupID})
262				}
263			}
264			var out strings.Builder
265			fmt.Fprintf(&out, "Usage:\n  %s\n  %s [command]\n", cmd.UseLine(), cmd.CommandPath())
266			width := 0
267			for _, entry := range ordered {
268				if !entry.command.Hidden && len(entry.name) > width {
269					width = len(entry.name)
270				}
271			}
272			terminalWidth := helpWidth
273			if terminalWidth == 0 {
274				terminalWidth = helpTerminalWidth(cmd.OutOrStderr())
275			}
276			for _, group := range cmd.Groups() {
277				fmt.Fprintf(&out, "\n%s\n", group.Title)
278				for _, entry := range ordered {
279					c := entry.command
280					if entry.group == group.ID && !c.Hidden && (c.IsAvailableCommand() || c.Name() == "help") {
281						writeHelpCommand(&out, entry.name, c.Short, width, terminalWidth)
282					}
283				}
284			}
285			if all, _ := cmd.Flags().GetBool("help-all"); all {
286				writeAllCommandHelp(&out, cmd, terminalWidth)
287			}
288			fmt.Fprintf(&out, "\nFlags:\n%s", cmd.LocalFlags().FlagUsages())
289			fmt.Fprintf(&out, "\nUse %q for more information about a command.\n", cmd.CommandPath()+" [command] --help")
290			_, err := io.WriteString(cmd.OutOrStderr(), out.String())
291			return err
292		})
293	}
294	
295	// List full paths without changing Hidden: all-help is an inspection surface,
296	// not a visibility change to the command tree or subsequent help invocations.
297	func writeAllCommandHelp(out io.Writer, root *cobra.Command, terminalWidth int) {
298		var commands []*cobra.Command
299		var paths []string
300		width := 0
301		var collect func(*cobra.Command, string)
302		collect = func(parent *cobra.Command, prefix string) {
303			for _, child := range parent.Commands() {
304				path := prefix + child.Name()
305				commands = append(commands, child)
306				paths = append(paths, path)
307				width = max(width, len(path))
308				collect(child, path+" ")
309			}
310		}
311		collect(root, "")
312		fmt.Fprintln(out, "\nAll commands (including developer and machine commands):")
313		for i, cmd := range commands {
314			writeHelpCommand(out, paths[i], cmd.Short, width, terminalWidth)
315		}
316	}
317	
318	// Prefer the output terminal. Entire may pipe plugin output, so also consult
319	// the controlling terminal for file-backed output. Unknown width means no wrap.
320	func helpTerminalWidth(out io.Writer) int {
321		if f, ok := out.(interface{ Fd() uintptr }); ok {
322			if width, _, err := term.GetSize(f.Fd()); err == nil && width > 0 {
323				return width
324			}
325			if tty, err := os.Open("/dev/tty"); err == nil {
326				defer tty.Close()
327				if width, _, err := term.GetSize(tty.Fd()); err == nil && width > 0 {
328					return width
329				}
330			}
331		}
332		if width, err := strconv.Atoi(os.Getenv("COLUMNS")); err == nil && width > 0 {
333			return width
334		}
335		return 0
336	}
337	
338	func writeHelpCommand(out io.Writer, name, description string, nameWidth, terminalWidth int) {
339		indent := nameWidth + 4
340		prefix := fmt.Sprintf("  %-*s  ", nameWidth, name)
341		if terminalWidth <= 0 || ansi.StringWidth(prefix+description) <= terminalWidth {
342			fmt.Fprintln(out, prefix+description)
343			return
344		}
345		// On very narrow terminals, put the description below the command name.
346		if terminalWidth <= indent {
347			fmt.Fprintf(out, "  %s\n", name)
348			indent = min(2, max(0, terminalWidth-1))
349			prefix = strings.Repeat(" ", indent)
350		}
351		wrapped := ansi.Wrap(description, max(1, terminalWidth-indent), "")
352		fmt.Fprintln(out, prefix+strings.ReplaceAll(wrapped, "\n", "\n"+strings.Repeat(" ", indent)))
353	}
354	
355	type commandJSONError struct {
356		Code    string `json:"code"`
357		Message string `json:"message"`
358	}
359	
360	// The rendered-error marker lives in cmdutil so extracted command packages can
361	// construct it; the alias keeps the package-local name for existing callers.
362	type renderedCommandError = cmdutil.RenderedCommandError
363	
364	var errRenderedCommand = renderedCommandError{}
365	
366	func RenderedError() error {
367		return errRenderedCommand
368	}
369	
370	func commandErrorWasRendered(err error) bool {
371		var rendered renderedCommandError
372		return errors.As(err, &rendered)
373	}
374	
375	func wrapJSONErrorRendering(cmd *cobra.Command) {
376		if cmd.Args != nil {
377			argsFunc := cmd.Args
378			cmd.Args = func(cmd *cobra.Command, args []string) error {
379				err := argsFunc(cmd, args)
380				if err == nil || !commandWantsJSONError(cmd) {
381					return err
382				}
383				_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
384				return renderedCommandError{Err: err}
385			}
386		}
387		if cmd.RunE != nil {
388			run := cmd.RunE
389			cmd.RunE = func(cmd *cobra.Command, args []string) error {
390				err := run(cmd, args)
391				if err == nil || !commandWantsJSONError(cmd) {
392					return err
393				}
394				if commandErrorWasRendered(err) {
395					return err
396				}
397				_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
398				return renderedCommandError{Err: err}
399			}
400		}
401		// CHAIN, do not replace. This walks every child, and a plain
402		// SetFlagErrorFunc here silently discarded any handler a command had set
403		// for itself -- which is how the `--symbol` hint on `inspect impact`
404		// vanished without a trace: the command set it, this overwrote it, and the
405		// user still saw cobra's bare "unknown flag".
406		//
407		// Any command may now improve its own flag error, and this still gets to
408		// render the JSON form on top.
409		prior := flagErrorFuncOf(cmd)
410		cmd.SetFlagErrorFunc(func(cmd *cobra.Command, err error) error {
411			if prior != nil {
412				err = prior(cmd, err)
413			}
414			if !commandWantsJSONError(cmd) {
415				return err
416			}
417			_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
418			return renderedCommandError{Err: err}
419		})
420		for _, child := range cmd.Commands() {
421			wrapJSONErrorRendering(child)
422		}
423	}
424	
425	// flagErrorFuncOf returns a command's OWN flag-error handler, or nil when it
426	// has none.
427	//
428	// cobra's FlagErrorFunc() walks up to the root when a command has not set one,
429	// so calling it directly would return the parent's and chain it to itself.
430	// Comparing against the parent's is what distinguishes "this command set one"
431	// from "this command inherited one".
432	func flagErrorFuncOf(cmd *cobra.Command) func(*cobra.Command, error) error {
433		own := cmd.FlagErrorFunc()
434		if own == nil || cmd.Parent() == nil {
435			return own
436		}
437		inherited := cmd.Parent().FlagErrorFunc()
438		if inherited != nil && reflect.ValueOf(own).Pointer() == reflect.ValueOf(inherited).Pointer() {
439			return nil
440		}
441		return own
442	}
443	
444	func commandWantsJSONError(cmd *cobra.Command) bool {
445		if flag := cmd.Flags().Lookup("format"); flag != nil && flag.Changed {
446			if wants, ok := commandFormatFlagWantsJSON(flag.Value.String()); ok {
447				return wants
448			}
449		}
450		if flag := cmd.InheritedFlags().Lookup("format"); flag != nil && flag.Changed {
451			if wants, ok := commandFormatFlagWantsJSON(flag.Value.String()); ok {
452				return wants
453			}
454		}
455		if wants, ok := commandRawFormatWantsJSON(append(cmd.Flags().Args(), commandRawArgs(cmd)...)); ok {
456			return wants
457		}
458		if flag := cmd.Flags().Lookup("json"); flag != nil && flag.Changed {
459			return commandJSONFlagEnabled(flag.Value.String())
460		}
461		if flag := cmd.InheritedFlags().Lookup("json"); flag != nil && flag.Changed {
462			return commandJSONFlagEnabled(flag.Value.String())
463		}
464		for _, arg := range append(cmd.Flags().Args(), commandRawArgs(cmd)...) {
465			if arg == "--json" {
466				return true
467			}
468			if strings.HasPrefix(arg, "--json=") {
469				value := strings.TrimPrefix(arg, "--json=")
470				return value == "" || value == "true" || value == "1"
471			}
472		}
473		return false
474	}
475	
476	func commandFormatFlagWantsJSON(value string) (bool, bool) {
477		switch strings.ToLower(strings.TrimSpace(value)) {
478		case "json":
479			return true, true
480		case "cli":
481			return false, true
482		default:
483			return false, false
484		}
485	}
486	
487	func commandRawFormatWantsJSON(args []string) (bool, bool) {
488		for i, arg := range args {
489			if arg == "--format" {
490				if i+1 >= len(args) {
491					return false, false
492				}
493				return commandFormatFlagWantsJSON(args[i+1])
494			}
495			if strings.HasPrefix(arg, "--format=") {
496				return commandFormatFlagWantsJSON(strings.TrimPrefix(arg, "--format="))
497			}
498		}
499		return false, false
500	}
501	
502	func commandJSONFlagEnabled(value string) bool {
503		value = strings.ToLower(value)
504		return value != "false" && value != "0"
505	}
506	
507	func commandRawArgs(cmd *cobra.Command) []string {
508		root := cmd.Root()
509		if root == nil {
510			return os.Args[1:]
511		}
512		value := reflect.ValueOf(root)
513		if value.Kind() != reflect.Pointer || value.IsNil() {
514			return os.Args[1:]
515		}
516		args := value.Elem().FieldByName("args")
517		if !args.IsValid() || args.Kind() != reflect.Slice || args.IsNil() {
518			return os.Args[1:]
519		}
520		out := make([]string, 0, args.Len())
521		for i := 0; i < args.Len(); i++ {
522			out = append(out, args.Index(i).String())
523		}
524		return out
525	}
