527	func writeCommandJSONError(w io.Writer, err error) error {
528		envelope := commandJSONError{
529			Code:    cmdutil.CommandErrorCode(err),
530			Message: err.Error(),
531		}
532		data, marshalErr := json.MarshalIndent(envelope, "", "  ")
533		if marshalErr != nil {
534			return marshalErr
535		}
536		_, writeErr := fmt.Fprintln(w, string(data))
537		return writeErr
538	}
