540	// legacyFlagAlias keeps a renamed flag's old spelling parseable by normalizing
541	// it to the new name. One per flag set: SetNormalizeFunc is single-slot, so a
542	// second call on the same FlagSet replaces the first.
543	func legacyFlagAlias(fs *pflag.FlagSet, oldName, newName string) {
544		fs.SetNormalizeFunc(func(f *pflag.FlagSet, name string) pflag.NormalizedName {
545			if name == oldName {
546				name = newName
547			}
548			return pflag.NormalizedName(name)
549		})
550	}
