50	// Execute runs the plugin root command with the real process environment.
51	func Execute(version string) error {
52		// Die with the dispatcher: a SIGKILLed `entire` cannot forward anything,
53		// and an orphaned mutation would hold the brain write lock to completion.
54		parentwatch.Arm()
55		cmd := NewRootCommand(Options{
56			Version: version,
57			Env:     base.EnvFromOS(),
58		})
59		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
60		defer stop()
61		if os.Getenv(parentwatch.DetachedEnv) != "" {
62			ctx = brainstore.BackgroundWrites(ctx)
63		}
64		err := cmd.ExecuteContext(ctx)
65		if err != nil && commandErrorWasRendered(err) {
66			return err
67		}
68		return err
69	}
